-- composition of rule kernels L:eliminate_filter x L:extract_equijoin_predicate (datafusion), template graft_exists
SELECT '0'::text AS c0, 10::bigint AS c1, 2 AS c2 FROM (SELECT * FROM tl WHERE EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb)) AS a1 GROUP BY a1.c1, a1.c0 HAVING TRUE;
